# [LATER-STEP] output_embedding.py\nimport os\nfrom model_client import get_llm_client\nfrom model_models import PromptRequest, normalize_response\n\ndef embed_output(text: str) -> List[float]:\n    \"\"\"Generate an embedding vector for the given text using a hosted embedding model.\"\"\"\n    provider = os.getenv(\"PROVIDER\", \"openai\").lower()\n    if provider == \"openai\":\n        import openai\n        openai.api_key = os.getenv(\"OPENAI_API_KEY\")\n        resp = openai.Embedding.create(model=\"text-embedding-3-large\", input=text)\n        return resp[\"data\"][0][\"embedding\"]\n    elif provider == \"google-genai\":\n        import google.generativeai as genai\n        genai.configure(api_key=os.getenv(\"GOOGLE_API_KEY\"))\n        model = genai.GenerativeModel(\"embedding-001\")\n        embedding = model.embed_content(text)\n        return embedding\n    elif provider == \"amazon\":\n        import boto3\n        bedrock = boto3.client(\"bedrock-runtime\")\n        response = bedrock.embed_content(\n            ModelId=\"amazon.titan.text-v1\",\n            Content=text,\n            ContentType=\"text/plain\",\n        )\n        # The response format may vary; assume list of floats\n        return response[\"Embedding\"][\"floatValues\"]\n    elif provider == \"dashscope\":\n        import dashscope\n        dashscope.api_key = os.getenv(\"DASHSCOPE_API_KEY\")\n        response = dashscope.text_embeddings(content=text, model=\"qwen2.5-32k\")\n        return response[\"embeddings\"][0][\"values\"]\n    elif provider == \"ibm\":\n        from ibm_watsonx_ai.services.embeddings import EmbeddingsService\n        service = EmbeddingsService()\n        # Authenticate via WATSONX_API_KEY and WATSONX_PROJECT_ID\n        service.set_api_key(os.getenv(\"WATSONX_API_KEY\"))\n        response = service.embed_documents([text])\n        return response.result[0][\"embedding\"]\n    elif provider == \"cohere\":\n        import cohere\n        cohere.api_key = os.getenv(\"COHERE_API_KEY\")\n        resp = cohere.Embed.create(model=\"embed-english-v3.0\", input=text)\n        return resp[\"embeddings\"][0][\"values\"]\n    else:\n        raise ValueError(f\"Unsupported PROVIDER: {provider}\")\n